import * as T from './assets/three.js';
const clamp=T.MathUtils.clamp;
const texture=(canvas,repeat=false)=>{const t=new T.CanvasTexture(canvas);t.colorSpace=T.SRGBColorSpace;t.anisotropy=8;if(repeat){t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(6,1.2)}return t};
function rgbHex(a){return '#'+a.map(v=>clamp(Math.round(v),0,255).toString(16).padStart(2,'0')).join('')}
function sampleColor(photo,start,end){const colors=[[],[],[]];for(let y=Math.floor(start);y<=Math.min(photo.bottom,end);y+=3){const row=photo.rows[y];if(!row||row.r<=row.l)continue;for(let x=Math.round(row.l+(row.r-row.l)*.1);x<row.r-(row.r-row.l)*.1;x+=4){const i=(y*photo.w+x)*4;if(photo.data.data[i+3]>200)for(let a=0;a<3;a++)colors[a].push(photo.data.data[i+a])}}return rgbHex(colors.map((a,i)=>{a.sort((x,y)=>x-y);return (a[Math.floor(a.length*.6)]??photo.rgb[i])*1.06}))}
export function analyzeParts(photo){const span=photo.bottom-photo.top,ratios=[];for(let i=0;i<100;i++){const row=photo.rows[Math.round(photo.top+span*i/100)];ratios.push(row?(row.r-row.l+1)/(photo.right-photo.left+1):1)}let seam=-1,min=.95;const begin=photo.ratio>.75?26:12,end=photo.ratio>.75?65:38;for(let i=begin;i<end;i++){if(ratios[i]<min){min=ratios[i];seam=i}}let capHeight=photo.ratio>.75?44:19,neckHeight=6,neckWidth=photo.ratio>.75?84:38;
if(seam>=0){let a=seam,b=seam;while(a>5&&ratios[a-1]<Math.max(.93,min+.035))a--;while(b<80&&ratios[b+1]<Math.max(.93,min+.035))b++;if(b-a<15){capHeight=a;neckHeight=Math.max(3,b-a+1);neckWidth=clamp(Math.round(min*100),30,95)}}
const bodyStart=photo.top+span*(capHeight+neckHeight)/100,bodyColor=sampleColor(photo,bodyStart,photo.bottom),capColor=sampleColor(photo,photo.top,photo.top+span*capHeight/100);
return {method:'parts',structure:photo.ratio>.75?'jar':'bottle',width:100,depth:55,capHeight,neckHeight,capWidth:photo.ratio>.75?100:58,neckWidth,shoulder:photo.ratio>.75?0:14,bevel:2,bodyColor,capColor,topColor:'#dedad2',neckColor:'#a08b72',roughness:photo.metal>.3?.65:.38,capRoughness:photo.metal>.3?.6:.32,metalness:photo.metal,grain:photo.metal>.3?60:15,labelStrength:75,labelText:'',topText:'',tolerance:35};}
function roundedShell(radius,height,y,material,bevel=.02,topRadius=radius,shoulder=0){const r=Math.max(.05,radius),b=Math.min(bevel,r*.15,height*.14),pts=[new T.Vector2(0,0),new T.Vector2(r-b,0)];for(let i=0;i<=8;i++){const a=-Math.PI/2+i*Math.PI/16;pts.push(new T.Vector2(r-b+b*Math.cos(a),b+b*Math.sin(a)))}if(shoulder>0){pts.push(new T.Vector2(r,height*(1-shoulder)));pts.push(new T.Vector2(topRadius,height-b))}else pts.push(new T.Vector2(r,height-b));for(let i=0;i<=8;i++){const a=i*Math.PI/16;pts.push(new T.Vector2(topRadius-b+b*Math.cos(a),height-b+b*Math.sin(a)))}pts.push(new T.Vector2(0,height));const geo=new T.LatheGeometry(pts,160,-Math.PI,2*Math.PI);const uv=geo.attributes.uv,pos=geo.attributes.position;for(let i=0;i<uv.count;i++)uv.setY(i,pos.getY(i)/height);const mesh=new T.Mesh(geo,material);mesh.position.y=y;return mesh}
function groupPart(root,name,mesh){const g=new T.Group();g.name=name;g.add(mesh);root.add(g);return g}
function grainMaterial(photo,start,end,color,roughness,metalness,strength){const n=192,canvas=document.createElement('canvas');canvas.width=canvas.height=n;const c=canvas.getContext('2d'),row=photo.rows[Math.round((start+end)/2)],left=row?.l??photo.left,right=row?.r??photo.right;const pw=Math.max(16,(right-left)*.22),ph=Math.max(8,(end-start)*.2);c.drawImage(photo.canvas,left+(right-left)*.32,start+(end-start)*.12,pw,ph,0,0,n,n);const original=c.getImageData(0,0,n,n),a=original.data,result=c.createImageData(n,n),rough=c.createImageData(n,n);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const i=(y*n+x)*4;let sum=0,count=0;for(let yy=Math.max(0,y-4);yy<=Math.min(n-1,y+4);yy+=2)for(let xx=Math.max(0,x-4);xx<=Math.min(n-1,x+4);xx+=2){const k=(yy*n+xx)*4;sum+=(a[k]+a[k+1]+a[k+2])/3;count++}const v=clamp(((a[i]+a[i+1]+a[i+2])/3-sum/count),-20,20)*strength/100;result.data.set([clamp(235+v*1.7,0,255),clamp(235+v*1.7,0,255),clamp(235+v*1.7,0,255),255],i);rough.data.set([clamp(220-v*1.5,0,255),clamp(220-v*1.5,0,255),clamp(220-v*1.5,0,255),255],i)}c.putImageData(result,0,0);const rc=document.createElement('canvas');rc.width=rc.height=n;rc.getContext('2d').putImageData(rough,0,0);const map=texture(canvas,true),roughMap=texture(rc,true);roughMap.colorSpace=T.NoColorSpace;return new T.MeshPhysicalMaterial({color,map,roughness,metalness,roughnessMap:roughMap,bumpMap:map,bumpScale:.009*strength/100,clearcoat:.12,clearcoatRoughness:.5,envMapIntensity:1.05})}
// Separate printing from the packaging surface; the can itself carries no baked light gradient.
function printMask(photo,start,end,config){const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=700;const ctx=canvas.getContext('2d');if(config.labelText.trim()){ctx.fillStyle='white';ctx.textAlign='center';ctx.textBaseline='middle';const lines=config.labelText.split('\n').slice(0,6);ctx.font=(lines.length>4?'45':'58')+'px Arial';lines.forEach((s,i)=>ctx.fillText(s,600,350+(i-(lines.length-1)/2)*80,1040));return canvas}
const h=Math.max(1,Math.round(end-start)),w=photo.right-photo.left+1,sample=document.createElement('canvas');sample.width=w;sample.height=h;const sc=sample.getContext('2d');sc.drawImage(photo.canvas,photo.left,start,w,h,0,0,w,h);const p=sc.getImageData(0,0,w,h),a=p.data,gray=new Float32Array(w*h);for(let i=0;i<gray.length;i++)gray[i]=(a[i*4]+a[i*4+1]+a[i*4+2])/3;
const residual=new Float32Array(w*h);for(let y=0;y<h;y++)for(let x=Math.floor(w*.13);x<w*.87;x++){if(y<h*.1||y>h*.96)continue;let sum=0,count=0;for(let yy=Math.max(0,y-11);yy<=Math.min(h-1,y+11);yy+=4)for(let xx=Math.max(0,x-15);xx<=Math.min(w-1,x+15);xx+=4){sum+=gray[yy*w+xx];count++}residual[y*w+x]=Math.abs(gray[y*w+x]-sum/count)}
const out=sc.createImageData(w,h);for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const i=y*w+x;if(residual[i]<10)continue;let neighbor=0;for(let yy=y-1;yy<=y+1;yy++)for(let xx=x-1;xx<=x+1;xx++)if(residual[yy*w+xx]>9)neighbor++;const alpha=neighbor>=4?clamp((residual[i]-10)*14,0,255)*config.labelStrength/100:0;out.data.set([255,255,255,alpha],i*4)}sc.putImageData(out,0,0);ctx.drawImage(sample,0,0,1200,700);return canvas}
export function createPartsModel(photo,input,extras={}){const c={...analyzeParts(photo),...input};const model=new T.Group();model.name='分件重建包装';const H=3,D=photo.ratio*H*c.width/100,R=D/2,capH=H*clamp(c.capHeight,6,65)/100,neckH=H*clamp(c.neckHeight,1,15)/100,bodyH=H-capH-neckH,span=photo.bottom-photo.top,capEnd=photo.top+span*c.capHeight/100,bodyStart=photo.top+span*(c.capHeight+c.neckHeight)/100;
const bodyMat=grainMaterial(photo,bodyStart,photo.bottom,c.bodyColor,c.roughness,c.metalness,c.grain),capMat=grainMaterial(photo,photo.top,capEnd,c.capColor,c.capRoughness,c.metalness,c.grain),neckMat=new T.MeshPhysicalMaterial({color:c.neckColor,metalness:Math.max(.4,c.metalness),roughness:.27}),edgeMat=new T.MeshPhysicalMaterial({color:c.capColor,metalness:Math.max(.7,c.metalness),roughness:.2});
if(c.structure==='box'){const front=bodyMat.clone(),frontCanvas=document.createElement('canvas');frontCanvas.width=frontCanvas.height=768;const fc=frontCanvas.getContext('2d');fc.fillStyle=c.bodyColor;fc.fillRect(0,0,768,768);fc.drawImage(photo.canvas,photo.left,photo.top,photo.right-photo.left+1,span,0,0,768,768);front.map=texture(frontCanvas);const back=bodyMat.clone();if(extras.back)back.map=texture(extras.back);const box=new T.Mesh(new T.BoxGeometry(D,H,D*c.depth/100),[bodyMat,bodyMat,capMat,bodyMat,front,back]);box.position.y=H/2;groupPart(model,'盒体',box);
}else{const body=roundedShell(R,bodyH,0,bodyMat,D*c.bevel/150,c.structure==='bottle'?R*c.neckWidth/100:R,c.structure==='bottle'?c.shoulder/100:0);groupPart(model,'罐身 / 瓶身',body);groupPart(model,'独立瓶颈',roundedShell(R*c.neckWidth/100,neckH,bodyH,neckMat,.012));const capR=R*c.capWidth/100;groupPart(model,'独立罐盖',roundedShell(capR,capH,bodyH+neckH,capMat,D*c.bevel/220));
const topMat=new T.MeshPhysicalMaterial({color:c.topColor,metalness:Math.min(.5,c.metalness),roughness:.47,clearcoat:.15,clearcoatRoughness:.5});if(extras.top)topMat.map=texture(extras.top);else if(c.topText.trim()){const can=document.createElement('canvas');can.width=can.height=1024;const tc=can.getContext('2d');tc.fillStyle=c.topColor;tc.fillRect(0,0,1024,1024);tc.fillStyle=c.neckColor;tc.font='82px Arial';tc.textAlign='center';tc.textBaseline='middle';tc.fillText(c.topText,512,512,780);topMat.color.set('#ffffff');topMat.map=texture(can)}const topFace=new T.Mesh(new T.CircleGeometry(capR*.975,160),topMat);topFace.rotation.x=-Math.PI/2;topFace.position.y=H+.003;groupPart(model,'独立顶盘',topFace);
const edgeGroup=new T.Group();edgeGroup.name='独立金属包边';for(const [r,y]of[[capR*.978,H+.004],[capR*.99,bodyH+neckH+.012],[R*.99,bodyH-.008]]){const ring=new T.Mesh(new T.TorusGeometry(Math.max(.02,r),.009,10,160),edgeMat);ring.rotation.x=Math.PI/2;ring.position.y=y;edgeGroup.add(ring)}model.add(edgeGroup);
const inkCanvas=printMask(photo,bodyStart,photo.bottom,c),ink=new T.MeshPhysicalMaterial({map:texture(inkCanvas),transparent:true,depthWrite:false,color:c.metalness>.35?'#c3a66a':'#554d3f',metalness:c.metalness>.35?.92:.05,roughness:c.metalness>.35?.23:.6,polygonOffset:true,polygonOffsetFactor:-1});const label=new T.Mesh(new T.CylinderGeometry(R+.002,R+.002,bodyH,96,1,true,-.84,1.68),ink);label.position.y=bodyH/2;label.name='独立印刷层';model.add(label);
if(extras.back){const backInk=new T.MeshPhysicalMaterial({map:texture(extras.back),transparent:true,metalness:0,roughness:.6});const labelBack=new T.Mesh(new T.CylinderGeometry(R+.003,R+.003,bodyH,96,1,true,Math.PI-.84,1.68),backInk);labelBack.position.y=bodyH/2;groupPart(model,'补充背标',labelBack)}
}
model.userData.partMethod=true;model.traverse(n=>{if(n.isMesh){n.castShadow=true;n.receiveShadow=true}});return model;}
